export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'ref'> {
  size?: number
  weight?: Weight
}

function make(name: keyof typeof PATHS) {
  function Icon({ size = 20, weight = 'regular', ...rest }: IconProps) {
    return (
      <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 256 256" fill="currentColor" {...rest}>
        {PATHS[name][weight].map((d) => (
          <path key={d} d={d} />
        ))}
      </svg>
    )
  }
  Icon.displayName = name
  return Icon
}

